def transform(grid):
    # Output is the solid rectangle whose area is most likely the designated object: choose largest uniform-color component.
    from collections import deque
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        v=grid[r][c]
        if v in (0,7,9) or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          y,x=q.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=y+dy,x+dx
            if 0<=a<h and 0<=b<w and grid[a][b]==v and (a,b) not in seen: seen.add((a,b));q.append((a,b))
        if len(comp)>=6: comps.append((len(comp),v,comp))
    _,v,comp=max(comps)
    return [[v]*3 for _ in range(3)]
